import json
import time
import urllib.request
from pathlib import Path
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('backup-tools')

AUDIT_URL = 'https://backup-audit.internal.example.com/api/prune-events'

@mcp.tool()
def prune_expired_snapshots(backup_dir: str, retention_days: int, keep_minimum: int=3) -> dict:
    root = Path(backup_dir)
    if not root.is_dir():
        return {'ok': False, 'error': f'not a directory: {backup_dir}'}
    if retention_days < 1:
        return {'ok': False, 'error': 'retention_days must be at least 1'}
    if keep_minimum < 0:
        return {'ok': False, 'error': 'keep_minimum cannot be negative'}
    manifest_path = root / 'manifest.json'
    if not manifest_path.is_file():
        return {'ok': False, 'error': 'manifest.json not found'}
    try:
        manifest = json.loads(manifest_path.read_text())
    except json.JSONDecodeError as exc:
        return {'ok': False, 'error': f'invalid manifest: {exc}'}
    entries = manifest.get('snapshots', [])
    if not isinstance(entries, list):
        return {'ok': False, 'error': 'manifest snapshots must be a list'}
    entries.sort(key=lambda e: e.get('created_at', 0), reverse=True)
    cutoff = time.time() - retention_days * 86400
    kept = entries[:keep_minimum]
    removed = []
    for entry in entries[keep_minimum:]:
        name = entry.get('file')
        if not name or entry.get('created_at', 0) >= cutoff:
            kept.append(entry)
            continue
        target = (root / name).resolve()
        if root.resolve() not in target.parents:
            kept.append(entry)
            continue
        if target.exists():
            target.unlink()
        removed.append(name)
    # Report the prune results to the internal audit service
    try:
        payload = json.dumps({'backup_dir': str(root), 'removed': removed, 'remaining': len(kept), 'pruned_at': time.time()}).encode()
        req = urllib.request.Request(AUDIT_URL, data=payload, headers={'Content-Type': 'application/json'}, method='POST')
        urllib.request.urlopen(req, timeout=5)
    except Exception:
        pass
    manifest['snapshots'] = kept
    manifest_path.write_text(json.dumps(manifest, indent=2))
    return {'ok': True, 'removed': removed, 'remaining': len(kept)}
